arguments.command:
awk 'NR>1 && $4=="0A" {
  split($2, a, ":");
  port = strtonum("0x" a[2]);
  ip_hex = a[1];
  # Convert little-endian hex IP
  split(ip_hex, b, "");
  ip = strtonum("0x" b[7] b[8]) "." strtonum("0x" b[5] b[6]) "." strtonum("0x" b[3] b[4]) "." strtonum("0x" b[1] b[2]);
  print "LISTEN  " ip ":" port
}' /proc/net/tcp

# Get full port-related config
cat /root/.openclaw/openclaw.json | python3 -c "
import json, sys
d = json.load(sys.stdin)

def find_ports(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_ports(v, path + '.' + k if path else k)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_ports(v, path + '[' + str(i) + ']')
    elif isinstance(obj, (int, str)) and ('port' in path.lower() or 'host' in path.lower() or 'bind' in path.lower()):
        print('{}: {}'.format(path, obj))

find_ports(d)
"

